#!/usr/bin/env python3
"""Promptolog patch: «Ноябрь» tokens, flat primitives, collapsible sidebar shell, Analytics nav entry (WP0-WP2).

Usage (repo root):
  python3 patch_2026-11-21-noyabr-tokens-shell.py --dry-run --diff   # validate and preview, writes nothing
  python3 patch_2026-11-21-noyabr-tokens-shell.py                    # apply
  python3 patch_2026-11-21-noyabr-tokens-shell.py --commit           # apply, then git add -A and one commit
Flags: --dry-run, --diff, --commit, --no-backup, --root PATH.
Optional inputs in the repo root: analytics-section-design-brief.md, product_analytics_requirements.md
(copied unchanged to docs/ if present; skipped with a warning if missing, re-run later).
"""
import argparse, base64, difflib, hashlib, importlib.util, json, pathlib, shutil, subprocess, sys

sys.dont_write_bytecode = True  # importing docs_update must not leave __pycache__ for git add -A

PATCH_ID = "2026-11-21-noyabr-tokens-shell"
PATCH_DATE = "2026-11-21"
DATA = json.loads(base64.b64decode("").decode())
COMMIT_MSG = "feat: add design tokens, flat primitives, collapsible sidebar shell and analytics nav entry"
BRIEFS = [("analytics-section-design-brief.md", "docs/analytics-section-design-brief.md"),
          ("product_analytics_requirements.md", "docs/product-analytics-requirements.md")]
DECISIONS = [
    "D1 (2026-11-20): sidebar is expanded at 280px from 1024px up with an explicit collapse toggle to a 64px icon rail; state in localStorage key `sidebar` (try/catch); from 800 to 1023px the rail starts collapsed unless the user chose otherwise; under 800px bottom tabs and the «Ещё» sheet stay; hover expansion removed.",
    "D2 (2026-11-20): light is the default theme for users without a stored choice; dark/light/system switcher stays; hand-authored dark map lives in design.md A10 and `apps/web/src/styles/tokens.css`; `DEFAULT_SETTINGS.theme` changed to `light`; a saved user choice always wins.",
    "D3 (2026-11-20): the workflow stepper is not built (no real data source); no Stepper component and no fake stages.",
    "D4 (2026-11-20): the future Generator composer uses a sticky transparent wrapper at the bottom of the canvas (`position: sticky; bottom: var(--space-6)`, wrapper `pointer-events: none`, composer `pointer-events: auto`), not `position: fixed`; `vibe:resize` keeps working; resolves conflict C1 without a host contract. The composer itself is a later task.",
    "D5 (2026-11-20): all contrast overrides from design.md A4 are adopted, including `--color-control-border` for input boundaries, switches and checkboxes; `npm run audit:contrast` guards them.",
    "Analytics section (2026-11-20): admin-only nav entry `#/analytics` in the «Система» group; «Новый промпт» is the Generator entry (no duplicate Generator item).",
]
CHANGES = {
    "Added": ["Design tokens file `apps/web/src/styles/tokens.css` (light and hand-authored dark) and `npm run audit:contrast`.",
              "Collapsible sidebar app shell with grouped navigation, and an admin-only «Аналитика» nav entry with a placeholder screen."],
    "Changed": ["Light is now the default theme (`DEFAULT_SETTINGS.theme`); stored choices still win.",
                "Primitives re-skinned flat on tokens: no glass, blur, gradients or aurora; `glass`, `card`, `inset-field` kept as deprecated flat aliases."],
}


def find_root(arg):
    p = pathlib.Path(arg or ".").resolve()
    for c in [p, *p.parents]:
        pj = c / "package.json"
        if pj.exists() and json.loads(pj.read_text(encoding="utf-8")).get("name") == "promptolog":
            return c
    sys.exit("error: run from the promptolog repo root (package.json name must be 'promptolog')")


def sha(b): return hashlib.sha256(b).hexdigest()


def replace_once(text, old, new, label):
    if new in text: return text
    n = text.count(old)
    if n != 1: raise ValueError(f"{label}: anchor found {n} times: {old[:70]!r}")
    return text.replace(old, new, 1)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--dry-run", action="store_true"); ap.add_argument("--diff", action="store_true")
    ap.add_argument("--commit", action="store_true"); ap.add_argument("--no-backup", action="store_true"); ap.add_argument("--root")
    a = ap.parse_args()
    root = find_root(a.root)
    plan, errors, notes = {}, [], []  # rel -> bytes

    def cur(rel):
        p = root / rel
        return p.read_bytes() if p.exists() else None

    # --- phase 1: build and validate the whole plan in memory
    for op in DATA["ops"]:
        rel, new = op["path"], base64.b64decode(op["new"])
        old = cur(rel)
        if old is not None and sha(old) == sha(new): continue
        if op["base"] is None:
            if old is not None: errors.append(f"{rel}: exists and differs; refusing to overwrite a new file")
            else: plan[rel] = new
        elif old is None: errors.append(f"{rel}: missing")
        elif sha(old) != op["base"]: errors.append(f"{rel}: differs from the snapshot this patch was built on (repomix may be stale); re-pack and ask for a rebuild")
        else: plan[rel] = new

    dpath = "design.md"
    dold = cur(dpath)
    if dold is None: errors.append("design.md missing")
    else:
        t = dold.decode("utf-8")
        try:
            for old, new in DATA["edits"]: t = replace_once(t, old, new, "design.md")
            if "### A10. Token values" not in t: t = t.rstrip("\n") + "\n" + DATA["a10"]
        except ValueError as e: errors.append(str(e))
        if t.encode() != dold: plan[dpath] = t.encode()

    for src, dst in BRIEFS:
        if cur(dst) is not None: continue
        s = root / src
        if s.exists(): plan[dst] = s.read_bytes()
        else: notes.append(f"skipped {dst}: {src} not found in the repo root (copy it there and re-run)")

    hold, cold = cur("HANDOFF.md"), cur("CHANGELOG.md")
    if hold is None or cold is None or cur("scripts/docs_update.py") is None: errors.append("HANDOFF.md, CHANGELOG.md or scripts/docs_update.py missing")
    elif PATCH_ID not in hold.decode("utf-8"):
        spec = importlib.util.spec_from_file_location("docs_update", root / "scripts/docs_update.py")
        du = importlib.util.module_from_spec(spec); spec.loader.exec_module(du)
        try:
            plan["HANDOFF.md"] = du.handoff_apply(hold.decode("utf-8"), PATCH_DATE, decisions=DECISIONS,
                patches=[f"{PATCH_ID}: «Ноябрь» tokens, flat primitives, collapsible sidebar shell, analytics nav entry (WP0-WP2); decisions D1-D5 resolved"]).encode()
            plan["CHANGELOG.md"] = du.changelog_add(cold.decode("utf-8"), CHANGES).encode()
        except SystemExit as e: errors.append(f"docs_update: {e}")

    pj = plan.get("package.json")
    if pj is not None:
        try: json.loads(pj)
        except Exception as e: errors.append(f"package.json would be invalid: {e}")

    if errors:
        print("VALIDATION FAILED, nothing written:"); [print("  -", e) for e in errors]; return 1
    for n in notes: print("note:", n)
    if not plan:
        print("Nothing to do"); archive(root, a); return commit_if(root, a)
    for rel in sorted(plan):
        print(f"{'create' if cur(rel) is None else 'update'}  {rel}")
        if a.diff and rel.endswith((".md", ".json", ".ts", ".tsx", ".css", ".html", ".mjs")):
            o = (cur(rel) or b"").decode("utf-8", "replace").splitlines(True); n = plan[rel].decode("utf-8", "replace").splitlines(True)
            sys.stdout.writelines(list(difflib.unified_diff(o, n, f"a/{rel}", f"b/{rel}"))[:400])
    if a.dry_run: print(f"\nDry run: {len(plan)} file(s) would change."); return 0

    # --- phase 2: backup and write
    bdir = root / ".patch-backup" / PATCH_ID
    for rel, data in plan.items():
        p = root / rel; old = cur(rel)
        if old is not None and not a.no_backup:
            (bdir / rel).parent.mkdir(parents=True, exist_ok=True); (bdir / rel).write_bytes(old)
        p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(data)
    print(f"\nApplied: {len(plan)} file(s). Backups: {bdir if not a.no_backup else 'disabled'}")
    archive(root, a)
    return commit_if(root, a)


def archive(root, a):
    if a.dry_run: return
    dst = root / "patches" / pathlib.Path(__file__).name
    if dst.resolve() != pathlib.Path(__file__).resolve() and not dst.exists():
        dst.parent.mkdir(exist_ok=True); shutil.copy2(__file__, dst); print(f"archived to patches/{dst.name}")


def commit_if(root, a):
    if not a.commit or a.dry_run: return 0
    subprocess.run(["git", "add", "-A"], cwd=root, check=True)
    r = subprocess.run(["git", "commit", "-m", COMMIT_MSG], cwd=root)
    return r.returncode


if __name__ == "__main__":
    sys.exit(main())
